EXTRAS = [
dict(n=31, gr='imper', vb='take,drink,rest,sleep,feel',
 c1="Dr. ou doctor?|Em inglês, 'doctor' (médico) é diferente de 'dentist' (dentista) e de 'pharmacist' (farmacêutico). Nos EUA a farmácia é 'drugstore' ou 'pharmacy'; no Reino Unido, 'chemist's'.",
 c2="Remédios sem receita|'Over-the-counter' (OTC) são remédios vendidos sem receita, como analgésicos e xaropes. Já 'prescription medicine' exige receita. Sempre leia a bula: 'Take one tablet twice a day'.",
 ar=("A bad cold","Sam wakes up with a sore throat and a cough. He feels tired and his head hurts. In the morning he stays in bed, but in the afternoon he goes to the pharmacy. Dina, the pharmacist, asks, \"What's the matter?\" Sam says, \"I have a cold.\" She gives him some syrup and says, \"Take it twice a day and drink a lot of water.\" At home Sam drinks hot tea with honey. Two days later he feels better and goes back to work.","Sam se trata de um resfriado com xarope, chá e descanso.","O que Sam tem?=A cold|A fever|A broken leg;;O que ele bebe em casa?=Hot tea with honey|Coffee|Cold milk"),
 ex="I'm feeling under the weather.=Estou meio mal.~Doença leve|Bless you!=Saúde!~Espirro|Get well soon!=Melhoras!~Desejo|I caught a cold.=Peguei um resfriado.~Doença|It's going around.=Está circulando.~Gripe no bairro",
 tf="Syrup é xarope.=T|Take it twice a day significa Tome duas vezes ao dia.=T|Sam tem uma perna quebrada.=F|Dina é professora.=F",
 odd="headache,cold,cough,table=table|tablet,syrup,medicine,bus=bus"),
dict(n=32, gr='should', vb='hurt,rest,exercise,drink,sleep',
 c1="Partes do corpo em inglês|Em inglês, o plural de 'foot' é 'feet' e o de 'tooth' é 'teeth': são irregulares! Para dizer onde dói, use 'My ___ hurts' (singular) ou 'My feet hurt' (plural).",
 c2="Saúde sem tradução|Em inglês, 'a check-up' é uma consulta de rotina e 'a shot' é uma injeção ou vacina. Nos EUA, 'insurance' é o plano de saúde e é muito importante em consultas médicas.",
 ar=("A visit to the doctor","Mei is a dentist, but today she is the patient. Her back hurts after a long week of work. Dr. Nina asks, \"Where does it hurt?\" Mei points to her lower back. Dr. Nina looks at it carefully and says, \"You should rest and do some stretching. You shouldn't carry heavy bags.\" Mei smiles. She knows this advice well: it is the same advice she gives to her own patients about their teeth and posture! She thanks the doctor and promises to follow every tip.","Mei, a dentista, vira paciente e ouve os conselhos que costuma dar.","Qual é a profissão de Mei?=Dentist|Doctor|Nurse;;O que Dr. Nina recomenda?=Rest and stretching|Surgery|Nothing"),
 ex="Where does it hurt?=Onde dói?~Médico|It hurts a lot.=Dói muito.~Paciente|Take it easy.=Vá com calma.~Conselho|I feel dizzy.=Estou tonto.~Sintoma|Let me take a look.=Deixe-me dar uma olhada.~Exame",
 tf="My back hurts significa Minhas costas doem.=T|Should dá conselho.=T|Mei é médica.=F|Foot no plural é foots.=F",
 odd="head,arm,leg,chair=chair|rest,sleep,exercise,carry=carry"),
dict(n=33, gr='comp', vb='try,wear,fit,buy,choose',
 c1="Tamanhos e medidas|Nos EUA, calçados têm numeração diferente da brasileira. Roupas costumam ser S, M, L e XL. Em inglês, 'fit' é servir: 'It fits me' (cabe em mim).",
 c2="Black Friday|Nos EUA, a Black Friday é o dia seguinte ao Thanksgiving, com grandes promoções. Em inglês, 'sale' é liquidação e 'discount' é desconto. 'Buy one, get one free' é leve um, ganhe outro.",
 ar=("The perfect coat","Lola needs a coat for winter. In the shop she tries on three. The black one is too big. The green one is too short. The red one fits perfectly. \"How much is it?\" asks Lola. Hugo, the shop assistant, says, \"It's sixty dollars, but today it's on sale.\" Lola smiles. \"I'll take it!\" She pays and wears the coat home. On the way, many people say, \"What a beautiful color!\" Lola feels warm and happy.","Lola prova três casacos e leva o vermelho, que serviu bem.","Qual casaco serve?=The red one|The black one|The green one;;Quanto custa?=Sixty dollars|Forty dollars|Ninety dollars"),
 ex="It's a perfect fit.=Ficou perfeito.~Roupa|It's not my style.=Não é meu estilo.~Gosto|Can I try this on?=Posso provar?~Loja|It's on sale.=Está em promoção.~Preço|I'll think about it.=Vou pensar.~Decidir depois",
 tf="Too big significa grande demais.=T|On sale significa em promoção.=T|O casaco vermelho ficou grande.=F|Hugo é cliente.=F",
 odd="coat,shirt,dress,sale=sale|big,small,long,coat=coat"),
dict(n=34, gr='be', vb='rain,snow,shine,wear,take',
 c1="O clima nas estações|Nos EUA, 'fall' é outono; no Reino Unido, 'autumn'. A primavera é 'spring', o verão 'summer' e o inverno 'winter'. Em inglês, 'it's raining cats and dogs' é chover muito.",
 c2="Fahrenheit ou Celsius?|Os EUA usam Fahrenheit: 32°F é 0°C e 100°F é 37,8°C. O Reino Unido usa Celsius, mas os mais velhos ainda falam em Fahrenheit. Em dúvida, pergunte 'What's the temperature?'.",
 ar=("Four seasons","On Maple Street the weather changes with the seasons. In spring it is warm and flowers are everywhere. In summer it is hot and sunny, and the kids play outside. In autumn it is cool and windy, and the leaves are red and yellow. In winter it is cold and sometimes snowy. People wear coats, hats and scarves. \"I love all four seasons,\" says Mia. \"Each one has something special.\" Her neighbors agree and drink hot chocolate on cold days.","As estações do ano deixam a rua com cara nova.","Como é o outono?=Cool and windy|Hot|Snowy;;O que as pessoas usam no inverno?=Coats and scarves|Shorts|Swimsuits"),
 ex="It's raining cats and dogs.=Está chovendo muito.~Idiom|Under the weather=Meio doente~Idiom|Break the ice=Quebrar o gelo~Conversa|A storm in a teacup=Tempestade em copo d'água~Exagero|Every cloud has a silver lining.=Há males que vêm para bem.~Provérbio",
 tf="Autumn é o outono.=T|Windy significa ensolarado.=F|It's raining é estar chovendo.=T|No inverno faz calor.=F",
 odd="sunny,rainy,windy,table=table|spring,summer,autumn,Monday=Monday"),
dict(n=35, gr='can', vb='call,send,text,answer,hear',
 c1="Atendendo o telefone|Em inglês, atende-se com 'Hello?' ou 'This is Jin speaking.' Para se identificar: 'It's Jin.' Para pedir para esperar: 'Hold on, please'. 'Hang up' é desligar.",
 c2="Emojis e abreviações|LOL (laughing out loud), BRB (be right back) e OMW (on my way) são abreviações comuns em mensagens. Os emojis também têm nomes: 'thumbs up' (joinha) e 'heart' (coração).",
 ar=("Bad signal","Jin is at the park and wants to call Aya. He dials her number, but the signal is terrible. \"Hello? Can you hear me?\" he says. Aya answers, \"I can't hear you well!\" Jin moves to the bridge and tries again. It is better, but still not good. Finally, he sends a text: \"Concert at 7 on Saturday. Are you coming?\" A minute later, Aya answers: \"Yes! See you there!\" Jin smiles and puts his phone in his pocket.","O sinal falha e uma mensagem de texto resolve.","Onde Jin está?=At the park|At home|At work;;O que Aya responde?=Yes! See you there!|No, sorry.|Maybe."),
 ex="Can you hear me?=Você está me ouvindo?~Ligação ruim|I'll call you back.=Eu te ligo de volta.~Retornar|Hold on a second.=Espere um segundo.~Pausa|You're breaking up.=Está falhando.~Sinal ruim|Let's keep in touch.=Vamos manter contato.~Despedida",
 tf="Hold on significa Aguarde.=T|Text pode ser verbo.=T|Jin está em casa.=F|O sinal estava ótimo.=F",
 odd="call,text,message,table=table|phone,signal,battery,bread=bread"),
dict(n=36, gr='there', vb='have,live,cook,sleep,sit',
 c1="Casa ou apartamento?|Nos EUA, 'house' é casa e 'apartment' é apartamento; no Reino Unido, 'flat' é apartamento. 'Ground floor' (UK) e 'first floor' (EUA) são o térreo. Muito comum: 'living room' (sala).",
 c2="Casas de bonecas|Quando crianças descrevem casas de brinquedo, usam 'there is' o tempo todo: 'There is a bed. There are two chairs.' Treinar com a sua própria casa é um ótimo exercício.",
 ar=("Rosa's new house","Rosa's new house is small but cozy. There is a living room with a green sofa and a big window. There is a kitchen with a wooden table. Upstairs there are two bedrooms and a bathroom. Behind the house there is a garden with a lemon tree. Max, her friend, walks through every room and says, \"It's lovely!\" \"There aren't many chairs yet,\" says Rosa. \"No problem,\" says Max. \"I have two old ones. I'll bring them tomorrow.\" Rosa smiles. A house becomes a home with friends.","Rosa mostra a casa nova e ganha cadeiras de um amigo.","De que cor é o sofá?=Green|Blue|Red;;O que há no jardim?=A lemon tree|A pool|A dog"),
 ex="Make yourself at home.=Fique à vontade.~Receber|Home sweet home.=Lar, doce lar.~Voltar para casa|Housewarming party=Festa de inauguração~Casa nova|There's no place like home.=Não há lugar como o lar.~Provérbio|It's cozy.=É aconchegante.~Descrever",
 tf="There is é usado com singular.=T|There are é usado com plural.=T|A casa de Rosa tem piscina.=F|Max traz duas cadeiras.=T",
 odd="sofa,bed,table,tree=tree|kitchen,bedroom,bathroom,garden=garden"),
dict(n=37, gr='wh', vb='rent,pay,sign,move,live',
 c1="Alugar em inglês|'Landlord' é o proprietário e 'tenant' é o inquilino. 'Rent' é o aluguel e 'deposit' é o depósito. O contrato é o 'lease' e o prazo costuma ser de 12 meses.",
 c2="Flatmates e roommates|No Reino Unido, quem divide a casa é 'flatmate'; nos EUA, 'roommate'. Em sites de aluguel você verá 'furnished' (mobiliado) e 'unfurnished' (vazio), e 'utilities' (contas de luz, água e gás).",
 ar=("A flat near the park","Cody is tired of his small room. He finds a bright flat near the park. It has two bedrooms, a balcony and a kitchen with a window. The rent is nine hundred dollars a month and there is a small deposit. The landlord, Isla, shows him every room. \"Is it furnished?\" asks Cody. \"Yes, there are a sofa, a bed and a table,\" says Isla. The street is quiet and the neighbors are friendly. Cody signs the lease and says, \"I'll take it!\"","Cody encontra um apartamento claro e assina o contrato.","Quanto custa o aluguel?=Nine hundred dollars|Five hundred dollars|Two thousand dollars;;O que o apartamento tem?=A balcony|A pool|A garage"),
 ex="I'm looking for a place.=Estou procurando um lugar.~Procura|Is it pet-friendly?=Aceita animais?~Pergunta|Utilities included?=Contas incluídas?~Aluguel|Move-in date=Data de entrada~Mudança|Sign here, please.=Assine aqui.~Contrato",
 tf="Landlord é o proprietário.=T|Lease é o contrato de aluguel.=T|Cody não gosta do apartamento.=F|O aluguel é de novecentos dólares.=T",
 odd="rent,deposit,lease,sofa=sofa|landlord,tenant,neighbor,balcony=balcony"),
dict(n=38, gr='can', vb='swim,run,dance,sing,cook',
 c1="Can ou be able to?|Can é a forma mais comum para habilidades: 'I can swim'. No passado, usa-se could: 'I could swim when I was five'. Para o futuro, 'will be able to'.",
 c2="Talentos famosos|Há pessoas com talentos incríveis: quem fala 10 idiomas é 'polyglot', quem toca vários instrumentos é 'multi-instrumentalist'. Em inglês, 'jack of all trades' é quem sabe fazer de tudo um pouco.",
 ar=("Learning from each other","Beto and Mara meet at the gym every Tuesday. Beto can swim and dance salsa, but he can't run fast. Mara can run very fast, but she can't swim. \"Can you teach me?\" asks Mara. \"Of course I can,\" says Beto. \"And can you teach me to run?\" \"Sure!\" They decide to help each other. On Tuesdays Beto teaches salsa and on Thursdays Mara teaches running. After one month, both can do something new and both are proud.","Beto e Mara trocam habilidades e aprendem juntos.","Quem corre rápido?=Mara|Beto|Pog;;Quando Beto ensina salsa?=Tuesday|Thursday|Sunday"),
 ex="I'm good at...=Sou bom em...~Habilidade|I'm not good at...=Não sou bom em...~Dificuldade|It's not my thing.=Não é a minha praia.~Gosto|Practice makes perfect.=A prática leva à perfeição.~Provérbio|You can do it!=Você consegue!~Incentivo",
 tf="Can é seguido do verbo sem to.=T|She can't swim significa Ela não sabe nadar.=T|Beto corre rápido.=F|Os dois se ajudam.=T",
 odd="swim,run,dance,gym=gym|can,can't,could,table=table"),
dict(n=39, gr='likeing', vb='like,love,hate,enjoy,listen',
 c1="Like, love, enjoy e hate|Depois de like, love, hate e enjoy, use verbo + -ing: 'I like reading'. 'Enjoy' sempre pede -ing ou substantivo: 'I enjoy music'. Nunca 'I enjoy to read'.",
 c2="Preferências culturais|Americanos adoram 'baseball' e 'football'; ingleses, 'football' (nosso futebol) e 'cricket'. Os gostos mudam por país. Conhecer o hobby do outro é uma ótima forma de puxar conversa.",
 ar=("New friends in the park","Sofia and Otto meet in the park on a sunny day. They sit on a bench and talk about their favorite things. Sofia likes music, painting and walking. Otto likes cycling, cooking and old movies. \"Do you like dancing?\" asks Sofia. \"Not really,\" says Otto, \"but I love listening to music.\" They both hate waking up early and love the weekend. They laugh and plan a bike ride to the lake on Sunday.","Sofia e Otto descobrem gostos em comum e planejam um passeio.","O que Otto gosta?=Cycling and cooking|Dancing|Running;;Para onde vão no domingo?=The lake|The beach|The school"),
 ex="I'm into music.=Curto música.~Gosto|It's not my cup of tea.=Não é a minha praia.~Não gostar|I'm crazy about it!=Sou louco por isso!~Paixão|I can't stand...=Não suporto...~Odiar|We have a lot in common.=Temos muito em comum.~Conexão",
 tf="I like reading usa -ing.=T|Enjoy pede to + verbo.=F|Hate é amar.=F|Sofia e Otto odeiam acordar cedo.=T",
 odd="music,movies,dancing,table=table|like,love,hate,hungry=hungry"),
dict(n=40, gr='there', vb='hurt,rest,have,like,rain',
 c1="Revisão dá resultado|Quando você revisa 3 temas juntos (casa, saúde e clima), seu cérebro cria conexões. Tente misturar: 'There is a doctor near my house. It's raining and I have a cold.'",
 c2="Feira de bairro|Muitas cidades têm 'health fairs' com exames gratuitos e 'garage sales' com objetos usados. Participar de eventos locais é um ótimo jeito de usar o inglês na prática.",
 ar=("A day at the fair","On Saturday there is a big fair on Maple Street. The doctors give advice, the neighbors show photos of their homes and the weather is sunny. People talk about headaches, gardens and favorite music. There is a stand with free tea and cake. A small band plays in the plaza. Children paint their faces. \"What a lovely day,\" says Mia. At night, there is a concert and everybody dances. They say goodbye with warm hugs and the promise to come back next month.","A feira de sábado junta saúde, casa e música.","Quando é a feira?=On Saturday|On Monday|On Friday;;O que acontece à noite?=A concert|A class|A race"),
 ex="Fingers crossed!=Dedos cruzados!~Torcida|Better safe than sorry.=Melhor prevenir.~Provérbio|It's a small world.=O mundo é pequeno.~Coincidência|Mind your health.=Cuide da saúde.~Conselho|Sounds like a plan.=Parece um bom plano.~Concordar",
 tf="No sábado há uma feira.=T|À noite há uma aula.=F|There is a stand with free tea.=T|O clima está chuvoso.=F",
 odd="doctor,fair,concert,pizza=pizza|house,garden,kitchen,Monday=Monday"),
]
